import { HTMLAttributes, useEffect, useState, useMemo } from 'preact/compat';
import { classes, Container, Slot, SlotProps } from '@adobe-commerce/elsie/lib';
import { useText } from '@adobe-commerce/elsie/i18n';
import { events } from '@adobe-commerce/event-bus';
import { ProductModel } from '@/pdp/data/models';
import { isDateValid, toDateString } from '@/pdp/lib/date';
import { config, getFetchedProductData } from '@/pdp/api';
import '@/pdp/containers/ProductAttributes/ProductAttributes.css';

type DefaultSlotContext = {
  data: ProductModel | null;
};

export interface ProductAttributesProps extends HTMLAttributes<HTMLDivElement> {
  scope?: string;
  formatValue?: (value: string, id: string, label: string) => string;
  slots?: {
    Attributes?: SlotProps<DefaultSlotContext>;
  };
}

export const ProductAttributes: Container<
  ProductAttributesProps,
  ProductModel | null
> = ({ initialData = null, scope, children, slots, formatValue, ...props }) => {
  const DetailsLabel = useText('PDP.Product.Details.label').label;
  const { globalLocale = 'en-US' } = config.getConfig();

  const [locale, setLocale] = useState<string>(globalLocale);
  const [data, setData] = useState<ProductModel | null>(initialData);

  const defaultSlotContext: DefaultSlotContext = useMemo(
    () => ({ data }),
    [data]
  );

  // Listen for events
  useEffect(() => {
    const dataEvent = events.on('pdp/data', setData, { scope });
    const localeEvent = events.on('locale', setLocale);

    return () => {
      dataEvent?.off();
      localeEvent?.off();
    };
  }, [scope]);

  if (!data) return null;

  return (
    <div {...props} className={classes(['pdp-attributes', props.className])}>
      <h2 className="pdp-attributes__title">{DetailsLabel}</h2>
      {slots?.Attributes ? (
        <Slot
          name="Attributes"
          slot={slots?.Attributes}
          context={{ ...defaultSlotContext }}
        />
      ) : (
        <ul>
          {data?.attributes?.map(
            (
              { id, label, value }: { id: string; label: string; value: any },
              index: number
            ) => {
              if (id?.startsWith('ac_') || !value) {
                return null;
              }

              const formatted = isDateValid(value)
                ? toDateString(value, locale)
                : value.toString();

              const __html = formatValue
                ? formatValue(formatted, id, label)
                : formatted;

              return (
                <li key={`attribute-${index}`}>
                  {/* eslint-disable-next-line react/no-danger */}
                  {label}: <span dangerouslySetInnerHTML={{ __html }} />
                </li>
              );
            }
          )}
        </ul>
      )}
    </div>
  );
};

ProductAttributes.getInitialData = getFetchedProductData;
